            /** @description Opaque. What DELETE /api/queued-actions/{id} takes. */
            id: string;
            /** @enum {string} */
            action: "update_branch" | "dependabot_rebase" | "renovate_rebase";
            forge: components["schemas"]["Forge"];
            /** @description "owner/repo". */
            fullName: string;
            number: number;
