    getCheckLog: {
        parameters: {
            query: {
                forge: components["schemas"]["Forge"];
                /** @description "owner/repo" of the repository the check ran in. */
                fullName: string;
                /** @description Matching a Check.jobId. */
                jobId: number;
                /**
                 * @description True to answer the job's excerpt (the last lines, at most 2,000
                 *     characters) instead of its output. Forgejo only; any other forge
                 *     answers 400.
                 */
                excerpt?: boolean;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The job's output, or its excerpt. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["CheckLog"];
                };
            };
            /** @description `fullName` wasn't "owner/repo", `jobId` wasn't a positive integer, no credentials are saved for that forge, or that forge's client can't read job logs. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No valid session cookie or token was presented. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The saved token's scope doesn't cover reading job logs, or it isn't allowed to see that repo. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The repository isn't one the dashboard tracks for you, or the forge has no such job or log (it expired, or the check isn't an Actions job). */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The forge rate-limited the request. */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The forge was unreachable, or answered with something this app couldn't classify more specifically. */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The dashboard has not loaded your repositories yet (a cold start or an outage), so it cannot say whether the repository is tracked. Retry shortly. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
